//	ffn_gate_shexp   row 2560   Q8_0 -> Q4_K   0.0393 GB a token saved
//	ffn_up_shexp     row 2560   Q8_0 -> Q4_K   0.0393
//	ffn_down_shexp   row  640   Q8_0 -> Q5_1   0.0246
//	ffn_down_exps    row  640   Q8_0 -> Q5_1   0.0256   (the 5 layers of 48)
